// @ts-check
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import mermaid from 'astro-mermaid';

/** A sidebar group listing every page in a docs folder. */
const folder = (label, directory) => ({
	label,
	collapsed: true,
	items: [{ autogenerate: { directory, collapsed: true } }],
});

// Autogenerated groups take their label from the folder name ("shader-node"), so groups are
// listed by hand. Unreal mirrors the Notion guides; Maya follows the old site's nav_order.
const unrealSidebar = [
	'unreal',
	'unreal/installation',
	folder('Artist Guide', 'unreal/artist-guide'),
	{
		label: 'Technical Artist Guide',
		collapsed: true,
		items: [
			'unreal/technical-artist-guide',
			'unreal/technical-artist-guide/breakdown',
			'unreal/technical-artist-guide/mix-and-match',
			folder('Effect Layers', 'unreal/technical-artist-guide/effect-layers'),
			folder('Post-Process Materials', 'unreal/technical-artist-guide/ppms'),
		],
	},
];

const mayaSidebar = [
	'maya',
	folder('Setup', 'maya/setup'),
	folder('Getting Started', 'maya/getting-started'),
	{
		label: 'Styles',
		collapsed: true,
		items: [
			'maya/styles',
			folder('Style Library', 'maya/styles/library'),
			'maya/styles/import-export',
		],
	},
	folder('Materials', 'maya/materials'),
	folder('Art-direction Tools', 'maya/art-direction'),
	'maya/toolbox',
	folder('Rendering', 'maya/rendering'),
	{
		label: 'Flair Graph',
		collapsed: true,
		items: [
			'maya/graph',
			'maya/graph/overview',
			'maya/graph/node-graph',
			folder('Shader Node', 'maya/graph/shader-node'),
			'maya/graph/read-node',
			'maya/graph/import-export-node',
			'maya/graph/display-node',
			'maya/graph/presets',
			'maya/graph/hotkeys',
			'maya/graph/expressions',
		],
	},
	'maya/release-log',
	'maya/uninstall',
	'maya/faq',
	folder('API', 'maya/api'),
	'maya/limitations',
];

export default defineConfig({
	site: 'https://docs.flair.graphics',
	integrations: [
		// Must come before Starlight, so mermaid code blocks become diagrams before Starlight's
		// code-block styling (Expressive Code) claims them.
		mermaid({ mermaidConfig: { look: 'handDrawn' } }),
		starlight({
			title: 'Flair',
			logo: { src: './src/assets/flair-logo.png', alt: '' },
			customCss: [
				'@fontsource/lato/400.css',
				'@fontsource/lato/400-italic.css',
				'@fontsource/lato/700.css',
				'@fontsource/josefin-sans/700.css',
				'./src/styles/chrome.css',
				'./src/styles/content.css',
			],
			pagination: false,
			head: [
				{ tag: 'script', attrs: { src: '/scripts/ui-screenshots.js', defer: true } },
				{ tag: 'script', attrs: { src: '/scripts/before-after.js', defer: true } },
			],
			sidebar: [
				{ label: 'Unreal Engine', items: unrealSidebar },
				{ label: 'Maya', items: mayaSidebar },
				folder('Effects', 'effects'),
				folder('Tools', 'tools'),
			],
			components: {
				Head: './src/components/HostHead.astro',
				PageTitle: './src/components/HostPageTitle.astro',
				Sidebar: './src/components/HostSidebar.astro',
				SiteTitle: './src/components/SiteTitle.astro',
				Hero: './src/components/home/HomeHero.astro',
			},
		}),
	],
	vite: {
		resolve: {
			alias: [
				{
					// Starlight's Search.astro creates the Pagefind UI internally and never exposes it,
					// so we can't call triggerFilters() from outside. Redirecting this exact import name
					// swaps in a host-aware subclass without copying Starlight's search component.
					// Only the bare name matches: the subclass's deep import and the CSS import pass through.
					find: /^@pagefind\/default-ui$/,
					replacement: fileURLToPath(new URL('./src/lib/host-pagefind-ui.ts', import.meta.url)),
				},
			],
		},
	},
});
